bodySchema:
{
  "type": "object",
  "properties": {
    "audio": {
      "description": "Audio settings",
      "enum": [
        "NONE",
        "ON",
        "OFF"
      ]
    },
    "fps": {
      "description": "Playback framerate",
      "type": "number"
    },
    "construct_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "frame": {
      "description": "Current timeline frame position",
      "type": "integer"
    },
    "timecodec": {
      "description": "Current timelinetimecode (readonly)",
      "type": "string"
    },
    "slot_idx": {
      "description": "Current Slot index being played in the timeline",
      "type": "integer"
    },
    "shot_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "shot_frame": {
      "description": "Current frame position in the Shot being played",
      "type": "integer"
    },
    "shot_timecode": {
      "description": "Current record timecode of the Shot being played (readonly)",
      "type": "string"
    },
    "version_idx": {
      "description": "Version index of the shot in the Player.",
      "type": "integer"
    },
    "session": {
      "description": "Session type the player is in. One of 'timeline,output,derived_output,shot,compare,slot' (readonly).",
      "type": "string"
    },
    "length": {
      "description": "Length of the media in the Player in frames",
      "type": "integer"
    },
    "loop": {
      "description": "Loop mode",
      "enum": [
        "ONCE",
        "LOOP",
        "BOUNCE"
      ]
    },
    "mark_in": {
      "description": "View range in-point",
      "type": "integer"
    },
    "mark_out": {
      "description": "View range out-point",
      "type": "integer"
    },
    "mode": {
      "description": "Playback mode",
      "enum": [
        "PAUSE",
        "PLAY_FRW",
        "PLAY_REV",
        "RECORD"
      ]
    },
    "range": {
      "description": "View range is active / not",
      "type": "boolean"
    },
    "speed": {
      "description": "Playback multiplier",
      "type": "integer"
    },
    "timeline": {
      "description": "Name of the construct being played",
      "type": "string"
    }
  }
}

