bodySchema:
{
  "type": "object",
  "title": "viewport_data",
  "description": "Player Viewport state. Lock view, output view, 360 view, single vs dual / over mode. Toggle RGB, luminance or alpha channel. Scale and position in image in the viewport.",
  "properties": {
    "view_mode": {
      "type": "string",
      "description": "View mode of the player. 'single' view show only the active node in the viewport. 'dual' splits the viewport to show a another node on the right side. 'over' mode overlays the active node with another node for comparisson, either using an A/B wipe or A-B difference view.",
      "enum": [
        "Single",
        "Dual",
        "Over A/B",
        "Over A-B"
      ]
    },
    "over_mode": {
      "type": "object",
      "title": "over_mode_data",
      "description": "Overlay settings. Only used when view_mode is 'over'.",
      "properties": {
        "wipe": {
          "type": "number",
          "description": "Wipe position in percent (A/B view).",
          "minimum": 0,
          "maximum": 100
        },
        "rotate": {
          "type": "number",
          "description": "Wipe rotation in degrees (A/B view).",
          "minimum": -360,
          "maximum": 360
        },
        "transparency": {
          "type": "number",
          "description": "Overlay transparency in percent (A/B view).",
          "readOnly": true,
          "minimum": 0,
          "maximum": 100
        },
        "gain": {
          "type": "number",
          "description": "Difference gain (A-B view).",
          "minimum": 0,
          "maximum": 100
        }
      }
    },
    "view_options": {
      "type": "object",
      "title": "view_options_data",
      "description": "View options of the main / left Viewport.",
      "properties": {
        "lock": {
          "type": "boolean",
          "description": "Lock the view to current selected node, allowing to navigate and alter other nodes in a composition while maintaining the view."
        },
        "output": {
          "type": "boolean",
          "description": "View the (main) output node of the timeline. This allows to view the final result of a (multi layered) timeline including framing and final grading and transforms, while working on selected timeline shot."
        },
        "spherical": {
          "type": "boolean",
          "description": "Enable / disable spherical (360) view mode."
        },
        "grade": {
          "type": "boolean",
          "description": "Enable / disable applying the color grade."
        },
        "overlay": {
          "type": "boolean",
          "description": "Toggle showing layer or plugin overlays in the view on/off."
        },
        "display_LUT": {
          "type": "boolean",
          "description": "Toggle applying the display LUT (if set) on/off."
        },
        "channel_mask": {
          "type": "string",
          "description": "Channel mask for the view: combination of R (Red), G (Green), B (Blue), M (Monochrome), L (Luminance), A (Alpha). Leaving the mask empty shows RGB channels. Enabling the Alpha channel, displays black when full opaque and white when full transparent. The mask is applied after the color grade and display LUT.",
          "example": "RGB"
        },
        "layout": {
          "type": "object",
          "title": "viewport_state_data",
          "description": "Pan/zoom state of a view in the Viewport.",
          "properties": {
            "center": {
              "type": "object",
              "description": "Normalized center of the image in the viewport.",
              "properties": {
                "x": {
                  "type": "number",
                  "description": "Normalized center x. 0.5 places the image horizontal center in the horizontal center of the viewport, 0.0 at the left edge."
                },
                "y": {
                  "type": "number",
                  "description": "Normalized center y. 0.5 places the image vertical center in the vertical center of the viewport, 0.0 at the bottom edge."
                }
              }
            },
            "scale": {
              "type": "number",
              "description": "Scale factor. 1.0 displays the image at 1:1 pixel ratio, 0.5 at half size."
            },
            "slip": {
              "type": "integer",
              "description": "Frame slip of the B view relative to the main view (applicable only with dual / over modes, through the view_options_b)."
            },
            "action": {
              "type": "string",
              "description": "Viewport action to scale the viewport image to a default size (input only, not returned with GET). '1 on 1' sets a 1:1 pixel ratio, 'fit' fits the image to the viewport, 'fullscreen_on'/'fullscreen_off' toggles the player fullscreen mode on or off.",
              "writeOnly": true,
              "enum": [
                "1 on 1",
                "fit",
                "fullscreen_on",
                "fullscreen_off"
              ]
            }
          }
        }
      }
    },
    "view_options_b": {
      "type": "object",
      "title": "view_options_b_data",
      "description": "View options of the right / B Viewport. Used only when view_mode is 'dual' or 'over'.",
      "properties": {
        "source": {
          "type": "string",
          "description": "Source node of the B view. 'Output' refers to the main output node of the current timeline. 'Current' shows the active node, the same as the left view (but with potential different view options). 'Tray' refers to the current selected tray item. 'Custom' requires shot_uuid to be set and allows to select any show to be viewed. 'Reference' refers to the shot set in the Editor as reference for the current timeline. 'All versions' refers to a viedeowall node creted from all versions in the current slot.",
          "enum": [
            "Output",
            "Current",
            "Tray",
            "Custom",
            "Reference",
            "All Versions"
          ]
        },
        "shot_uuid": {
          "type": "string",
          "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
          "minLength": 36,
          "maxLength": 36,
          "description": "UUID format as per RFC 4122"
        },
        "over_mode": {
          "type": "object",
          "title": "over_mode_data",
          "description": "Overlay settings. Only used when view_mode is 'over'.",
          "properties": {
            "wipe": {
              "type": "number",
              "description": "Wipe position in percent (A/B view).",
              "minimum": 0,
              "maximum": 100
            },
            "rotate": {
              "type": "number",
              "description": "Wipe rotation in degrees (A/B view).",
              "minimum": -360,
              "maximum": 360
            },
            "transparency": {
              "type": "number",
              "description": "Overlay transparency in percent (A/B view).",
              "readOnly": true,
              "minimum": 0,
              "maximum": 100
            },
            "gain": {
              "type": "number",
              "description": "Difference gain (A-B view).",
              "minimum": 0,
              "maximum": 100
            }
          }
        },
        "spherical": {
          "type": "boolean",
          "description": "Enable / disable spherical (360) view mode."
        },
        "grade": {
          "type": "boolean",
          "description": "Enable / disable applying the color grade."
        },
        "link": {
          "type": "boolean",
          "description": "Link the pan/zoom of both views."
        },
        "display_LUT": {
          "type": "boolean",
          "description": "Toggle applying the display LUT (if set) on/off."
        },
        "channel_mask": {
          "type": "string",
          "description": "Channel mask for the view: combination of R (Red), G (Green), B (Blue), M (Monochrome), L (Luminance), A (Alpha). Leaving the mask empty shows RGB channels. Enabling the Alpha channel, displays black when full opaque and white when full transparent. The mask is applied after the color grade and display LUT.",
          "example": "RGB"
        },
        "layout": {
          "type": "object",
          "title": "viewport_state_data",
          "description": "Pan/zoom state of a view in the Viewport.",
          "properties": {
            "center": {
              "type": "object",
              "description": "Normalized center of the image in the viewport.",
              "properties": {
                "x": {
                  "type": "number",
                  "description": "Normalized center x. 0.5 places the image horizontal center in the horizontal center of the viewport, 0.0 at the left edge."
                },
                "y": {
                  "type": "number",
                  "description": "Normalized center y. 0.5 places the image vertical center in the vertical center of the viewport, 0.0 at the bottom edge."
                }
              }
            },
            "scale": {
              "type": "number",
              "description": "Scale factor. 1.0 displays the image at 1:1 pixel ratio, 0.5 at half size."
            },
            "slip": {
              "type": "integer",
              "description": "Frame slip of the B view relative to the main view (applicable only with dual / over modes, through the view_options_b)."
            },
            "action": {
              "type": "string",
              "description": "Viewport action to scale the viewport image to a default size (input only, not returned with GET). '1 on 1' sets a 1:1 pixel ratio, 'fit' fits the image to the viewport, 'fullscreen_on'/'fullscreen_off' toggles the player fullscreen mode on or off.",
              "writeOnly": true,
              "enum": [
                "1 on 1",
                "fit",
                "fullscreen_on",
                "fullscreen_off"
              ]
            }
          }
        }
      }
    }
  }
}

