{
  "type": "object",
  "description": "Settings for copying a grade and node controls from a source- to a destination Shot / Layer",
  "required": [
    "src_uuid",
    "dst_uuid"
  ],
  "properties": {
    "src_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "dst_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "src_layer_idx": {
      "type": "integer",
      "description": "Index of the layer of the source Shot to copy from. When omitted or negative, the primary grade of the source Shot is used, including all layers and node controls."
    },
    "dst_layer_idx": {
      "type": "integer",
      "description": "Index of the layer of the destination Shot to copy to. When omitted or negative, the primary grade of the destination Shot is targeted."
    },
    "paste_options": {
      "type": "object",
      "description": "Determines which elements of a grade are copied. These options correspond to the options in the Paste Options panel in the Player. When omitted (or when no option is enabled), the selected paste-options of the current user profile are used.",
      "example": {
        "all": false,
        "grade": true,
        "grade_animations": true,
        "curves": true,
        "lut": true
      },
      "properties": {
        "all": {
          "type": "boolean",
          "description": "Copy all elements of the source grade (node controls, grade, curves, vectors, media source, LUT, layers, framing and their animations)."
        },
        "node_controls": {
          "type": "boolean",
          "description": "Copy the node specific controls (e.g. plugin controls, decode options for media reader nodes, etc.)."
        },
        "non_default": {
          "type": "boolean",
          "description": "Option to only copy the node specific controls that differ from their default value (+ Non-Default)."
        },
        "grade": {
          "type": "boolean",
          "description": "Copy the primary grade (Levels, Color and Numeric menus)."
        },
        "grade_animations": {
          "type": "boolean",
          "description": "Include all animations of the primary grade in the grade (+Animation)."
        },
        "curves": {
          "type": "boolean",
          "description": "Copy the settings from the Curves menu."
        },
        "vectors": {
          "type": "boolean",
          "description": "Copy the settings from the Vectors menu (remapping)."
        },
        "media_source": {
          "type": "boolean",
          "description": "Copy the settings of the source remapping of the source node."
        },
        "lut": {
          "type": "boolean",
          "description": "Copy the LUT settings."
        },
        "layers": {
          "type": "boolean",
          "description": "Copy all the layers from the source grade."
        },
        "layer_animations": {
          "type": "boolean",
          "description": "Also copy the animations of the layers (+Animation)."
        },
        "add_layers": {
          "type": "boolean",
          "description": "Add the copied layers to the destination node, leaving the existing layers intact (Add Layers)."
        },
        "fill_matte": {
          "type": "boolean",
          "description": "Also copy the fill and matte texture nodes of the layers (+Texture)."
        },
        "framing": {
          "type": "boolean",
          "description": "Copy the framing settings."
        },
        "framing_animations": {
          "type": "boolean",
          "description": "Also copy the animations of the framing (+Animation)."
        },
        "animations_relative": {
          "type": "boolean",
          "description": "Paste animation channels relative to the in-point of the destination node instead of using the absolute position of the source Shot (A. Relative)."
        }
      }
    }
  }
}

{
  "type": "object",
  "description": "Settings for creating a snapshot image of a Shot",
  "properties": {
    "uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "frame": {
      "type": "integer",
      "description": "Frame number to create the image from"
    },
    "proxy": {
      "type": "boolean",
      "description": "Create a proxy image or of the source size"
    },
    "file": {
      "type": "string",
      "description": "Full file path name on the local http server. Supported file formats are *.png, *.jpg, *.tif."
    },
    "mime_type": {
      "type": "string",
      "description": "Mime type of the image data when no file path is provided. The image data is returned to the client. Supported mime types are image/png, image/jpeg."
    }
  }
}

