    },
    "file": {
      "type": "string",
      "description": "Full file path name on the local http server. Supported file formats are *.cube, *.3dl, *.lut, *.xml and *.txt."
    },
    "lut_type": {
      "type": "string",
      "description": "LUT type to be generated. Supported LUT types are cube, 3dl, lut, xml and txt."
    }
  }
}

