            "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
            "minLength": 36,
            "maxLength": 36,
            "description": "UUID format as per RFC 4122"
          },
          "input": {
            "description": "Recursive reference",
            "type": "object"
          },
          "length": {
            "type": "integer",
            "description": "Length of the Input Shot in frames"
          },
          "loop_mode": {
            "enum": [
              "Once",
              "Loop",
              "Bounce",
              "Reverse"
            ],
            "description": "Loop mode of the Input Shot"
          },
          "slip": {
            "type": "integer",
            "description": "Shot in-point."
          }
        }
      }
    },
    "controls": {
      "type": "array",
      "items": {
        "type": "object",
        "title": "control_data",
        "description": "Individual control data item",
        "required": [
          "id",
          "value"
        ],
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the control (readonly)"
          },
          "name": {
            "type": "string",
            "description": "Name of the control"
          },
          "type": {
            "type": "string",
            "description": "Type of the control - 'Option', 'Text', 'Boolean', etc. (readonly)",
            "enum": [
              "Option",
              "Text",
              "MText",
              "Boolean",
              "Numeric",
              "Color",
              "Menu"
            ]
          },
          "value": {
            "description": "Value of the control (string representation for all types)",
            "oneOf": [
              {
                "type": "boolean"
              },
              {
                "type": "string"
              },
              {
                "type": "number"
              },
              {
                "type": "object",
                "properties": {
                  "r": {
                    "type": "number",
                    "description": "Red channel value"
                  },
                  "g": {
                    "type": "number",
                    "description": "Green channel value"
                  },
                  "b": {
                    "type": "number",
                    "description": "Blue channel value"
                  },
                  "a": {
                    "type": "number",
                    "description": "Alpha channel value",
                    "required": [
                      "r",
                      "g",
                      "b",
                      "a"
                    ],
                    "additionalProperties": false
                  }
                }
              }
            ]
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "description": "Move or copy the Shot to a different location in the Project",
  "properties": {
    "create_copy": {
      "type": "boolean",
      "description": "Create a copy of the Shot"
    },
    "construct_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "slot_idx": {
      "type": "integer",
      "description": "Move the Shot to a Slot with slot_id in the Construct"
    },
    "version_idx": {
      "type": "integer",
      "description": "Move the Shot to the version index in the Slot, by default 0 is used which puts the shot at the bottom of the slot"
    },
    "tray_name": {
      "type": "string",
      "description": "Move the Shot to the Tray with name"
    },
    "tray_frame": {
      "type": "integer",
      "description": "The frame to use for the proxy image"
    },
    "tray_slip": {
      "type": "integer",
      "description": "The frame slip to use when playing in split view"
    },
    "tray_position": {
      "type": "integer",
      "description": "Position index in the tray"
    },
    "tray_create": {
      "type": "boolean",
      "description": "Create a new tray if tray-name it does not exist"
    }
  }
}

