    "create_copy": {
      "type": "boolean",
      "description": "Create a copy of the Construct or move it"
    },
    "construct_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "group_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "position_index": {
      "type": "integer",
      "description": "Position index in the Group to move or copy the Construct to"
    }
  }
}

