              "scale": {
                "type": "object",
                "description": "2D Vector",
                "properties": {
                  "x": {
                    "description": "x value",
                    "type": "number"
                  },
                  "y": {
                    "description": "y value",
                    "type": "number"
                  }
                }
              },
              "rotate": {
                "type": "number",
                "description": "Rotation angle in degrees"
              },
              "opacity": {
                "type": "number",
                "description": "Opacity percentage"
              },
              "animation": {
                "type": "object",
                "properties": {
                  "channels": {
                    "description": "List of animation channels",
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "id": {
                          "type": "string",
                          "description": "Name of the Animation channel"
                        },
                        "key_frames": {
                          "type": "array",
