bodySchema:
{
  "type": "object",
  "description": "Shot data",
  "title": "Shot data",
  "properties": {
    "uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "type_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "file": {
      "type": "string",
      "description": "Full filename of the Shot media"
    },
    "name": {
      "description": "Name of the Shot",
      "type": "string"
    },
    "node_preset_file": {
      "description": "File path to the .pls (plugin preset) file. Input only.",
      "type": "string"
    },
    "color_settings_file": {
      "description": "File path to the .ccr (color settings) file. Input only",
      "type": "string"
    },
    "reel_id": {
      "type": "string",
      "description": "Reel identifier"
    },
    "scene": {
      "description": "Scene identifier",
      "type": "string"
    },
    "take": {
      "description": "Take identifier",
      "type": "string"
    },
    "circled": {
      "description": "Circle Shot y/n",
      "type": "boolean"
    },
    "fps": {
      "type": "number",
      "description": "Frames per second of the shot"
    },
    "fps_multiplier": {
      "description": "FPS multiplier for retiming",
      "type": "number"
    },
    "fps_offset": {
      "description": "FPS offset for retiming",
      "type": "number"
    },
    "fps_mode": {
      "description": "FPS mode for retiming (0 = Nearest Frame, 1 = Rolling Mix)",
      "type": "integer"
    },
    "frame_tc": {
      "type": "integer",
      "description": "Frame number of the Shot timecode"
    },
    "timecode": {
      "type": "string",
      "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
      "minLength": 11,
      "maxLength": 11,
      "description": "Timecode HH:MM:SS:FF"
    },
    "length": {
      "type": "integer",
      "description": "Length of the Shot in frames"
    },
    "handles": {
      "type": "object",
      "properties": {
        "frame_in": {
          "type": "integer",
          "description": "In-point of the Shot"
        },
        "frame_out": {
          "type": "integer",
          "description": "Out-point of the Shot"
        },
        "start": {
          "type": "string",
          "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
          "minLength": 11,
          "maxLength": 11,
          "description": "Timecode HH:MM:SS:FF"
        },
        "end": {
          "type": "string",
          "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
          "minLength": 11,
          "maxLength": 11,
          "description": "Timecode HH:MM:SS:FF"
        }
      }
    },
    "size": {
      "type": "object",
      "description": "Resolution of the Shot in pixels",
      "properties": {
        "width": {
          "type": "integer"
        },
        "height": {
          "type": "integer"
        }
      }
    },
    "aspect": {
      "type": "number",
      "description": "Aspect ratio of the Shot"
    },
    "output": {
      "type": "object",
      "description": "Output settings for rendering the individual Shot",
      "properties": {
        "outputpath": {
          "type": "string",
          "description": "Output folder for the render"
        },
        "filespec": {
          "type": "string",
          "description": "File specification / mask for the render. Include mask codes to dynamically create the output filename. See the documentation for details."
        },
        "format": {
          "type": "integer",
          "description": "Format mask is a combination of bit depth and component type. 0 (8bit), 1 (10bit), 2 (16bit int), 3 (16bit float), 4 (32bit float). Note that most media formats only allow for specific combinations of bit depth and type. Not all combinations are valid. Check the sotware UI for valid combinations."
        },
        "components": {
          "type": "integer",
          "description": "Channel count (3 for RGB, 4 for RGBA)"
        },
        "extention": {
          "enum": [
            "tif",
            "dpx",
            "cin",
            "jpg",
            "tga",
            "j2c",
            "png",
            "exr"
          ],
          "description": "File extension"
        }
      }
    },
    "framing": {
      "type": "object",
      "description": "Shot framing in a timeline context",
      "properties": {
        "offset": {
          "type": "object",
          "description": "2D Vector",
          "properties": {
            "x": {
              "description": "x value",
              "type": "number"
            },
            "y": {
              "description": "y value",
              "type": "number"
            }
          }
        },
        "scale": {
          "type": "object",
          "description": "2D Vector",
          "properties": {
            "x": {
              "description": "x value",
              "type": "number"
            },
            "y": {
              "description": "y value",
              "type": "number"
            }
          }
        },
        "rotate": {
          "type": "number",
          "description": "Rotation angle in degrees"
        },
        "opacity": {
          "type": "number",
          "description": "Opacity percentage"
        },
        "animation": {
          "type": "object",
          "properties": {
            "channels": {
              "description": "List of animation channels",
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "Name of the Animation channel"
                  },
                  "key_frames": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "li": {
                          "type": "number",
                          "description": "Left tangent line position"
                        },
                        "lv": {
                          "type": "number",
                          "description": "Left tangent line value"
                        },
                        "ki": {
                          "type": "number",
                          "description": "Key position"
                        },
                        "kv": {
                          "type": "number",
                          "description": "Key value"
                        },
                        "ri": {
                          "type": "number",
                          "description": "Right tangent line position"
                        },
                        "rv": {
                          "type": "number",
                          "description": "Right tangent line value"
                        }
                      },
                      "required": [
                        "ki",
                        "kv"
                      ]
                    }
                  },
                  "pre": {
                    "type": "string",
                    "description": "Pre interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                  },
                  "post": {
                    "type": "string",
                    "description": "Post interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                  }
                }
              }
            }
          }
        }
      }
    },
    "view": {
      "type": "object",
      "properties": {
        "projection_type": {
          "description": "Projection type",
          "enum": [
            "normal",
            "equirectangular 360",
            "equirectangular-180",
            "cubic",
            "cubic-packed",
            "mesh"
          ]
        },
        "stereo_mode": {
          "description": "Stereo mode",
          "enum": [
            "mono",
            "stereo",
            "left-right",
            "top-bottom"
          ]
        }
      }
    },
    "orientation": {
      "type": "object",
      "description": "Shot Orientation",
      "properties": {
        "flip": {
          "type": "boolean",
          "description": "Invert Shot horizontally"
        },
        "flop": {
          "type": "boolean",
          "description": "Invert Shot vertically"
        }
      }
    },
    "color_format": {
      "type": "object",
      "description": "Color format of the Shot",
      "properties": {
        "colorspace": {
          "description": "Color space",
          "enum": [
            "ACES (AP0)",
            "ACEScg (AP1)",
            "Adobe RGB (1998)",
            "Adobe Wide Gamut",
            "Apple Wide Gamut",
            "ARRI Wide Gamut 3",
            "ARRI Wide Gamut 4",
            "Blackmagic DWG",
            "BMD Wide Gamut",
            "Canon Cinema Gamut",
            "DCI XYZ",
            "DJI D-Gamut",
            "Fujifilm F-Gamut C",
            "P3 D60",
            "P3 D65",
            "P3 DCI",
            "Panasonic V-Gamut",
            "Rec2020",
            "Rec709",
            "RED Wide Gamut",
            "Sony S-Gamut3",
            "Sony S-Gamut3 Cine",
            "sRGB",
            "XYZ"
          ]
        },
        "eotf": {
          "description": "EOTF (Electro-Optical Transfer Function)",
          "enum": [
            "ACEScc",
            "ACEScct",
            "Apple Log",
            "ARRI LogC3",
            "ARRI LogC4",
            "Blackmagic DI",
            "BMD Film",
            "BMD Film Gen 5",
            "Canon Log2",
            "Canon Log3",
            "Cineon Log",
            "DJI D-Log",
            "Fujifilm F-Log",
            "Fujifilm F-Log2",
            "Gamma 2.2",
            "Gamma 2.4",
            "Gamma 2.6 (DCI)",
            "HLG HDR",
            "HLG Scene HDR",
            "Leica L-Log",
            "Nikon N-Log",
            "Panasonic V-Log",
            "PQ HDR",
            "RED Log3G10",
            "Scene Linear",
            "Sony S-Log2",
            "Sony S-Log3"
          ]
        },
        "apply": {
          "type": "boolean",
          "description": "Apply an automatic transformation on the node input if the color space or transfer function differs (only available with Transformer nodes)"
        },
        "lut": {
          "type": "string",
          "description": "LUT applied to the shot"
        }
      }
    },
    "colorgrade": {
      "type": "object",
      "title": "colorgrade",
      "description": "Shot colorgrade metadata",
      "properties": {
        "offset": {
          "type": "object",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel offset"
            },
            "g": {
              "type": "number",
              "description": "Green channel offset"
            },
            "m": {
              "type": "number",
              "description": "Master offset"
            },
            "r": {
              "type": "number",
              "description": "Red channel offset"
            }
          }
        },
        "pre_gain": {
          "type": "object",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel pre gain"
            },
            "g": {
              "type": "number",
              "description": "Green channel pre gain"
            },
            "m": {
              "type": "number",
              "description": "Master pre gain"
            },
            "r": {
              "type": "number",
              "description": "Red channel pre gain"
            }
          }
        },
        "color_a": {
          "type": "object",
          "description": "Pre-Color",
          "properties": {
            "h": {
              "type": "number",
