                              "enum": [
                                "Option",
                                "Text",
                                "MText",
                                "Boolean",
                                "Numeric",
                                "Color",
                                "Menu"
                              ]
                            },
                            "value": {
                              "description": "Value of the control (string representation for all types)",
                              "oneOf": [
                                {
                                  "type": "boolean"
                                },
                                {
                                  "type": "string"
                                },
                                {
                                  "type": "number"
                                },
                                {
                                  "type": "object",
                                  "properties": {
                                    "r": {
                                      "type": "number",
                                      "description": "Red channel value"
                                    },
                                    "g": {
                                      "type": "number",
                                      "description": "Green channel value"
                                    },
                                    "b": {
                                      "type": "number",
                                      "description": "Blue channel value"
                                    },
                                    "a": {
                                      "type": "number",
                                      "description": "Alpha channel value",
                                      "required": [
                                        "r",
                                        "g",
                                        "b",
                                        "a"
                                      ],
                                      "additionalProperties": false
                                    }
                                  }
                                }
                              ]
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "smode": {
                  "type": "string",
                  "description": "Slot playmode in case the Slot length differs from the Shot length.",
                  "enum": [
                    "Once",
                    "Loop",
                    "Bounce",
                    "Reverse",
                    "RLoop",
                    "RBounce"
                  ]
                },
                "timecode": {
                  "type": "string",
                  "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
                  "minLength": 11,
                  "maxLength": 11,
                  "description": "Timecode HH:MM:SS:FF"
                },
                "transition": {
                  "type": "object",
                  "required": [
                    "after",
                    "before",
                    "type"
                  ],
                  "properties": {
                    "after": {
                      "description": "number of frames the transition covers after the cut",
                      "type": "integer"
                    },
                    "before": {
                      "description": "number of frames the transition covers before the cut",
                      "type": "integer"
                    },
                    "type": {
                      "description": "Type of transition",
                      "enum": [
                        "Cut",
                        "Additive",
                        "Dissolve",
                        "Optical",
                        "Fade",
                        "Wipe"
                      ]
                    },
                    "wipe": {
                      "description": "Wipe sub-type when main transition type is set to Wipe",
                      "type": "integer"
                    },
                    "reverse": {
                      "description": "Whether the transition is reversed",
                      "type": "boolean"
                    },
                    "dist": {
                      "description": "Distance in pixels that will be smoothed of between shots",
                      "type": "number"
                    },
                    "gamma_neutral": {
                      "description": "Use a gamma neutral transition",
                      "type": "boolean"
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

