              "type": "number",
              "description": "Rotation Z"
            },
            "manual": {
              "description": "Auto position the virtual camera based on focal length",
              "type": "boolean"
            },
            "pscale": {
              "description": "Pixel meter scale",
              "type": "number"
            }
          }
        },
        "offset": {
          "type": "object",
          "description": "Camera offset position and rotation",
          "properties": {
            "tx": {
              "type": "number",
              "description": "Translation X"
            },
            "ty": {
              "type": "number",
              "description": "Translation Y"
            },
            "tz": {
              "type": "number",
              "description": "Translation Z"
            },
            "rx": {
              "type": "number",
              "description": "Rotation X"
            },
            "ry": {
              "type": "number",
              "description": "Rotation Y"
            },
            "rz": {
              "type": "number"
            }
          }
        },
        "animation": {
          "type": "object",
          "properties": {
            "channels": {
              "description": "List of animation channels",
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "Name of the Animation channel"
                  },
                  "key_frames": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "li": {
                          "type": "number",
                          "description": "Left tangent line position"
                        },
                        "lv": {
                          "type": "number",
                          "description": "Left tangent line value"
                        },
                        "ki": {
                          "type": "number",
                          "description": "Key position"
                        },
                        "kv": {
                          "type": "number",
                          "description": "Key value"
                        },
                        "ri": {
                          "type": "number",
                          "description": "Right tangent line position"
                        },
                        "rv": {
                          "type": "number",
                          "description": "Right tangent line value"
                        }
                      },
                      "required": [
                        "ki",
                        "kv"
                      ]
                    }
                  },
                  "pre": {
                    "type": "string",
                    "description": "Pre interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                  },
                  "post": {
                    "type": "string",
                    "description": "Post interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                  }
                }
              }
            }
          }
        }
      }
    },
    "mos": {
      "type": "boolean",
      "description": "Mit Ohne Sound Shot"
    },
    "audio": {
      "type": "object",
      "description": "Audio settings of the Shot",
      "properties": {
        "timecode": {
          "type": "string",
          "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
          "minLength": 11,
          "maxLength": 11,
          "description": "Timecode HH:MM:SS:FF"
        },
        "slip": {
          "type": "number",
          "description": "Slip in milliseconds of all audio items to the video"
        },
        "roll": {
          "type": "number",
          "description": "Roll identifier"
        },
        "items": {
          "type": "array",
          "description": "List of audio items",
          "items": {
            "type": "object",
            "properties": {
              "file": {
                "type": "string",
                "description": "File path of the audio item. 'embedded' if the Shot has embedded audio."
              },
              "offset": {
                "type": "integer",
                "description": "Offset in milliseconds of the individual audio item to the video"
              }
            }
          }
        }
      }
    },
    "metadata": {
      "type": "array",
      "title": "Metadata",
      "description": "Metadata list of key-value pairs",
      "items": {
        "type": "object",
        "properties": {
          "key": {
            "type": "string",
            "description": "Metadata key"
          },
          "value": {
            "type": "string",
            "description": "Metadata value"
          }
        }
      }
    },
    "notes": {
      "type": "array",
      "description": "Notes of the Shot",
      "items": {
        "type": "object",
        "title": "note_data",
        "description": "Note",
        "properties": {
          "status": {
            "type": "integer",
            "description": "Color of the note"
          },
          "author": {
            "type": "string",
            "description": "Author of the note"
          },
          "frame": {
            "type": "integer",
            "description": "Frame number in the Shot of the note"
          },
          "id": {
            "type": "integer",
            "description": "Unique identifier of the note"
          },
          "note": {
            "type": "string",
            "description": "Content of the note"
          }
        }
      }
    },
    "staging": {
      "type": "array",
      "description": "List of Staging Shots",
      "items": {
        "type": "object",
        "properties": {
          "stage_shot_uuid": {
            "type": "string",
            "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
            "minLength": 36,
            "maxLength": 36,
            "description": "UUID format as per RFC 4122"
          },
          "shot": {
            "description": "Recursive reference",
            "type": "object"
          }
        }
      }
    },
    "inputs": {
      "type": "array",
      "items": {
        "type": "object",
        "title": "input_data",
        "description": "Input Shot of a (parent) Shot",
        "properties": {
          "index": {
            "type": "integer",
            "description": "Index of the Input Shot in the parent Shot"
          },
          "grade": {
            "type": "boolean",
            "description": "render the grade of the Input Shot"
          },
          "create_copy": {
            "type": "boolean",
            "description": "Create a copy of the Shot or use a reference"
          },
          "input_uuid": {
            "type": "string",
            "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
            "minLength": 36,
            "maxLength": 36,
            "description": "UUID format as per RFC 4122"
          },
          "input": {
            "description": "Recursive reference",
            "type": "object"
          },
          "length": {
            "type": "integer",
            "description": "Length of the Input Shot in frames"
          },
          "loop_mode": {
            "enum": [
              "Once",
              "Loop",
              "Bounce",
              "Reverse"
            ],
            "description": "Loop mode of the Input Shot"
          },
          "slip": {
            "type": "integer",
            "description": "Shot in-point."
          }
        }
      }
    },
    "controls": {
      "type": "array",
      "items": {
        "type": "object",
        "title": "control_data",
        "description": "Individual control data item",
        "required": [
          "id",
          "value"
        ],
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier of the control (readonly)"
          },
          "name": {
            "type": "string",
            "description": "Name of the control"
          },
          "type": {
            "type": "string",
            "description": "Type of the control - 'Option', 'Text', 'Boolean', etc. (readonly)",
            "enum": [
              "Option",
              "Text",
              "MText",
              "Boolean",
              "Numeric",
              "Color",
              "Menu"
            ]
          },
          "value": {
            "description": "Value of the control (string representation for all types)",
            "oneOf": [
              {
                "type": "boolean"
              },
              {
                "type": "string"
              },
              {
                "type": "number"
              },
              {
                "type": "object",
                "properties": {
                  "r": {
                    "type": "number",
                    "description": "Red channel value"
                  },
                  "g": {
                    "type": "number",
                    "description": "Green channel value"
                  },
                  "b": {
                    "type": "number",
                    "description": "Blue channel value"
                  },
                  "a": {
                    "type": "number",
                    "description": "Alpha channel value",
                    "required": [
                      "r",
                      "g",
                      "b",
                      "a"
                    ],
                    "additionalProperties": false
                  }
                }
              }
            ]
          }
        }
      }
    }
  }
}

{
  "type": "object",
