bodySchema:
{
  "type": "object",
  "title": "layer_data",
  "description": "A layer has its own color grade, shape, softness, color qualifier, animation, fill, matte etc",
  "properties": {
    "name": {
      "description": "Name of the layer",
      "type": "string"
    },
    "active": {
      "type": "boolean",
      "description": "Is the layer active"
    },
    "selected": {
      "type": "boolean",
      "description": "Whether the layer is selected"
    },
    "recursive": {
      "type": "boolean",
      "description": "Whether the layer settings are applied recursively to all layers below in the stack"
    },
    "group": {
      "type": "boolean",
      "description": "Whether the layer is a group layer containing sub-layers"
    },
    "parent": {
      "type": "integer",
      "description": "Index of the parent layer."
    },
    "colorgrade": {
      "type": "object",
      "title": "colorgrade",
      "description": "Shot colorgrade metadata",
      "properties": {
        "offset": {
          "type": "object",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel offset"
            },
            "g": {
              "type": "number",
              "description": "Green channel offset"
            },
            "m": {
              "type": "number",
              "description": "Master offset"
            },
            "r": {
              "type": "number",
              "description": "Red channel offset"
            }
          }
        },
        "pre_gain": {
          "type": "object",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel pre gain"
            },
            "g": {
              "type": "number",
              "description": "Green channel pre gain"
            },
            "m": {
              "type": "number",
              "description": "Master pre gain"
            },
            "r": {
              "type": "number",
              "description": "Red channel pre gain"
            }
          }
        },
        "color_a": {
          "type": "object",
          "description": "Pre-Color",
          "properties": {
            "h": {
              "type": "number",
              "description": "Hue"
            },
            "l": {
              "type": "number",
              "description": "Brightness"
            },
            "s": {
              "type": "number",
              "description": "Saturation"
            }
          }
        },
        "lift": {
          "type": "object",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel lift"
            },
            "g": {
              "type": "number",
              "description": "Green channel lift"
            },
            "m": {
              "type": "number",
              "description": "Master lift"
            },
            "r": {
              "type": "number",
              "description": "Red channel lift"
            }
          }
        },
        "gamma": {
          "type": "object",
          "description": "Gamma",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel gamma"
            },
            "g": {
              "type": "number",
              "description": "Green channel gamma"
            },
            "r": {
              "type": "number",
              "description": "Red channel gamma"
            },
            "m": {
              "type": "number",
              "description": "Master gamma"
            }
          }
        },
        "gain": {
          "type": "object",
          "description": "Gain",
          "properties": {
            "b": {
              "type": "number",
              "description": "Blue channel gain"
            },
            "g": {
              "type": "number",
              "description": "Green channel gain"
            },
            "r": {
              "type": "number",
              "description": "Red channel gain"
            },
            "m": {
              "type": "number",
              "description": "Master gain"
            }
          }
        },
        "color_b": {
          "type": "object",
          "description": "Post-Color",
          "properties": {
            "h": {
              "type": "number",
              "description": "Hue"
            },
            "l": {
              "type": "number",
              "description": "Brightness"
            },
            "s": {
              "type": "number",
              "description": "Saturation"
            }
          }
        },
        "tone": {
          "type": "object",
          "properties": {
            "c": {
              "type": "number",
              "description": "Contrast"
            },
            "i": {
              "type": "number",
              "description": "ISO Gain"
            },
            "s": {
              "type": "number",
              "description": "S Curve"
            }
          }
        },
        "temperature": {
          "type": "object",
          "properties": {
            "k": {
              "type": "number",
              "description": "Kelvin temperature"
            },
            "t": {
              "type": "number",
              "description": "Tint"
            }
          }
        },
        "aperature": {
          "type": "object",
          "title": "Aperature",
          "description": "Aperature",
          "properties": {
            "c": {
              "type": "number",
              "description": "Clarity"
            },
            "d": {
              "type": "number",
              "description": "Defocus"
            }
          }
        },
        "noise": {
          "type": "number",
          "description": "Amount of noise to add to the shot"
        },
        "channel_invert": {
          "type": "boolean",
          "description": "Whether to invert the color channels"
        },
        "channel_remap": {
          "type": "string",
          "pattern": "^[RBG0]{3}[A0RGB1]$",
          "minLength": 4,
          "maxLength": 4,
          "description": "Remapping of color channels"
        },
        "soft_clip_high": {
          "type": "object",
          "description": "Soft clip high value",
          "properties": {
            "r": {
              "type": "number",
              "description": "Red channel soft clip high value"
            },
            "g": {
              "type": "number",
              "description": "Green channel soft clip high value"
            },
            "b": {
              "type": "number",
              "description": "Blue channel soft clip high value"
            }
          }
        },
        "soft_clip_low": {
          "type": "object",
          "description": "Soft clip low value",
          "properties": {
            "r": {
              "type": "number",
              "description": "Red channel soft clip low value"
            },
            "g": {
              "type": "number",
              "description": "Green channel soft clip low value"
            },
            "b": {
              "type": "number",
              "description": "Blue channel soft clip low value"
            }
          }
        },
        "clip_high": {
          "type": "object",
          "description": "Clip high value",
          "properties": {
            "r": {
              "type": "number",
              "description": "Red channel clip high value"
            },
            "g": {
              "type": "number",
              "description": "Green channel clip high value"
            },
            "b": {
              "type": "number",
              "description": "Blue channel clip high value"
            }
          }
        },
        "clip_low": {
          "type": "object",
          "description": "Clip low value",
          "properties": {
            "r": {
              "type": "number",
              "description": "Red channel clip low value"
            },
            "g": {
              "type": "number",
              "description": "Green channel clip low value"
            },
            "b": {
              "type": "number",
              "description": "Blue channel clip low value"
            }
          }
        },
        "lut": {
          "type": "string",
          "description": "LUT applied to the colorgrade"
        }
      }
    },
    "canvas": {
      "type": "object",
      "title": "canvas_data",
      "description": "A Canvas represents the ouline and position, rotation and scale of a layer",
      "properties": {
        "alpha": {
          "type": "number",
          "description": "Opacity of the canvas"
        },
        "softness": {
          "type": "number",
          "description": "The Softness parameter determines how far away from the Canvas shape the softness effect will extend"
        },
        "xform": {
          "type": "object",
          "description": "Transform properties of the canvas",
          "properties": {
            "pivot": {
              "type": "object",
              "description": "3D Vector",
              "properties": {
                "x": {
                  "description": "x value",
                  "type": "number"
                },
                "y": {
                  "description": "y value",
                  "type": "number"
                },
                "z": {
                  "description": "z value",
                  "type": "number"
                }
              }
            },
            "rotate": {
              "type": "object",
              "description": "3D Vector",
              "properties": {
                "x": {
                  "description": "x value",
                  "type": "number"
                },
                "y": {
                  "description": "y value",
                  "type": "number"
                },
                "z": {
                  "description": "z value",
                  "type": "number"
                }
              }
            },
            "scale": {
              "type": "object",
              "description": "3D Vector",
              "properties": {
                "x": {
                  "description": "x value",
                  "type": "number"
                },
                "y": {
                  "description": "y value",
                  "type": "number"
                },
                "z": {
                  "description": "z value",
                  "type": "number"
                }
              }
            },
            "translate": {
              "type": "object",
              "description": "3D Vector",
              "properties": {
                "x": {
                  "description": "x value",
                  "type": "number"
                },
                "y": {
                  "description": "y value",
                  "type": "number"
                },
                "z": {
                  "description": "z value",
                  "type": "number"
                }
              }
            }
          }
        }
      }
    },
    "fill": {
      "type": "object",
      "title": "fill_data",
      "description": "A Fill represents the image part of a layer",
      "properties": {
        "shot_uuid": {
          "type": "string",
          "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
          "minLength": 36,
          "maxLength": 36,
          "description": "UUID format as per RFC 4122"
        },
        "blend_mode": {
          "type": "string",
          "description": "Blend mode of the fill",
          "enum": [
            "Normal",
            "Over",
            "Add",
            "Subtract",
            "Multiply",
            "Screen",
            "Overlay",
            "Dodge",
            "Burn",
            "Lighten",
            "Darken",
            "Negate",
            "Soft Light",
            "Hard Light",
            "Difference",
            "Exclusion",
            "Color",
            "Luminosity"
          ]
        },
        "blur": {
          "type": "number",
          "description": "Amount of blur to apply to the fill"
        },
        "blur_angle": {
          "type": "number",
          "description": "Angle of the blur to apply to the fill"
        },
        "blur_dir_active": {
          "type": "boolean",
          "description": "Whether the blur direction is active for the fill"
        },
        "channel_mask": {
          "type": "object",
          "description": "Channel mask for the fill",
          "properties": {
            "R": {
              "type": "boolean",
              "description": "Red channel mask"
            },
            "G": {
              "type": "boolean",
              "description": "Green channel mask"
            },
            "B": {
              "type": "boolean",
              "description": "Blue channel mask"
            },
            "A": {
              "type": "boolean",
              "description": "Alpha channel mask"
            }
          }
        },
        "map": {
          "type": "string",
          "description": "Map file path for the fill",
          "enum": [
            "Projected",
            "On Canvas",
            "Pinned"
          ]
        },
        "slip": {
          "type": "number",
          "description": "Slip in frames of the fill"
        },
        "orientation": {
          "type": "object",
          "description": "Fill orientation",
          "properties": {
            "rot": {
              "type": "number",
              "description": "Rotation angle of the fill in degrees"
            },
            "sx": {
              "type": "number",
              "description": "Horizontal scale of the fill"
            },
            "sy": {
              "type": "number",
              "description": "Vertical scale of the fill"
            },
            "tx": {
              "type": "number",
              "description": "Horizontal translation of the fill"
            },
            "ty": {
              "type": "number",
              "description": "Vertical translation of the fill"
            }
          }
        },
        "warp": {
          "type": "string",
          "description": "Warp type of the fill",
          "enum": [
            "None",
            "Equi360",
            "Equi180"
          ]
        },
        "warp_blur_filter": {
          "type": "number",
          "description": "Warp blur filter"
        },
        "warp_equi_dist": {
          "type": "number",
          "description": "Warp equi distance"
        }
      }
    },
    "matte": {
      "type": "object",
      "title": "matte_data",
      "description": "A Matte represents the image part of a layer",
      "properties": {
        "shot_uuid": {
          "type": "string",
          "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
          "minLength": 36,
          "maxLength": 36,
          "description": "UUID format as per RFC 4122"
        },
        "blend_mode": {
          "type": "string",
          "description": "Blend mode of the matte",
          "enum": [
            "None",
            "Over",
            "Add",
            "Subtract",
            "Copy"
          ]
        },
        "blur": {
          "type": "number",
          "description": "Amount of blur to apply to the matte"
        },
        "blur_angle": {
          "type": "number",
          "description": "Angle of the blur to apply to the matte"
        },
        "blur_dir_active": {
          "type": "boolean",
          "description": "Whether the blur direction is active for the matte"
        },
        "channel_mask": {
          "type": "object",
          "description": "Channel mask for the matte",
          "properties": {
            "R": {
              "type": "boolean",
              "description": "Red channel matte"
            },
            "G": {
              "type": "boolean",
              "description": "Green channel mask"
            },
            "B": {
              "type": "boolean",
              "description": "Blue channel mask"
            },
            "A": {
              "type": "boolean",
              "description": "Alpha channel mask"
            }
          }
        },
        "map": {
          "type": "string",
          "description": "Map file path for the matte",
          "enum": [
            "Projected",
            "On Canvas",
            "Pinned"
          ]
        },
        "slip": {
          "type": "number",
          "description": "Slip in frames of the matte"
        },
        "orientation": {
          "type": "object",
          "description": "Matte orientation",
          "properties": {
            "rot": {
              "type": "number",
              "description": "Rotation angle of the matte in degrees"
            },
            "sx": {
              "type": "number",
              "description": "Horizontal scale of the matte"
            },
            "sy": {
              "type": "number",
              "description": "Vertical scale of the matte"
            },
            "tx": {
              "type": "number",
              "description": "Horizontal translation of the matte"
            },
            "ty": {
              "type": "number",
              "description": "Vertical translation of the matte"
            }
          }
        },
        "warp": {
          "type": "string",
          "description": "Warp type of the matte",
          "enum": [
            "None",
            "Equi360",
            "Equi180"
          ]
        },
        "warp_blur_filter": {
          "type": "number",
          "description": "Warp blur filter"
        },
        "warp_equi_dist": {
          "type": "number",
          "description": "Warp equi distance"
        }
      }
    }
  }
}

