              "type": "number",
              "description": "Tint"
            }
          }
        },
        "aperature": {
          "type": "object",
          "title": "Aperature",
          "description": "Aperature",
          "properties": {
            "c": {
              "type": "number",
              "description": "Clarity"
            },
            "d": {
              "type": "number",
              "description": "Defocus"
            }
          }
        },
        "noise": {
          "type": "number",
          "description": "Amount of noise to add to the shot"
        },
        "channel_invert": {
          "type": "boolean",
