            "Over",
            "Add",
            "Subtract",
            "Multiply",
            "Screen",
            "Overlay",
            "Dodge",
            "Burn",
            "Lighten",
            "Darken",
            "Negate",
            "Soft Light",
            "Hard Light",
            "Difference",
            "Exclusion",
            "Color",
            "Luminosity"
          ]
        },
