            "Equi180"
          ]
        },
        "warp_blur_filter": {
          "type": "number",
          "description": "Warp blur filter"
        },
        "warp_equi_dist": {
          "type": "number",
          "description": "Warp equi distance"
        }
      }
    }
  }
}

