      "type": "string",
      "description": "Warp type of the fill",
      "enum": [
        "None",
        "Equi360",
        "Equi180"
      ]
    },
    "warp_blur_filter": {
      "type": "number",
      "description": "Warp blur filter"
    },
    "warp_equi_dist": {
      "type": "number",
      "description": "Warp equi distance"
    }
  }
}

{
  "type": "object",
  "title": "matte_data",
  "description": "A Matte represents the image part of a layer",
  "properties": {
    "shot_uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "blend_mode": {
      "type": "string",
      "description": "Blend mode of the matte",
      "enum": [
        "None",
        "Over",
        "Add",
        "Subtract",
        "Copy"
      ]
    },
    "blur": {
      "type": "number",
      "description": "Amount of blur to apply to the matte"
    },
    "blur_angle": {
      "type": "number",
      "description": "Angle of the blur to apply to the matte"
    },
    "blur_dir_active": {
      "type": "boolean",
      "description": "Whether the blur direction is active for the matte"
    },
    "channel_mask": {
      "type": "object",
      "description": "Channel mask for the matte",
      "properties": {
        "R": {
          "type": "boolean",
          "description": "Red channel matte"
        },
        "G": {
          "type": "boolean",
          "description": "Green channel mask"
        },
        "B": {
          "type": "boolean",
          "description": "Blue channel mask"
        },
        "A": {
          "type": "boolean",
          "description": "Alpha channel mask"
        }
      }
    },
    "map": {
      "type": "string",
      "description": "Map file path for the matte",
      "enum": [
        "Projected",
        "On Canvas",
        "Pinned"
      ]
    },
    "slip": {
      "type": "number",
      "description": "Slip in frames of the matte"
    },
    "orientation": {
      "type": "object",
      "description": "Matte orientation",
      "properties": {
        "rot": {
          "type": "number",
          "description": "Rotation angle of the matte in degrees"
        },
        "sx": {
          "type": "number",
          "description": "Horizontal scale of the matte"
        },
        "sy": {
          "type": "number",
          "description": "Vertical scale of the matte"
        },
        "tx": {
          "type": "number",
          "description": "Horizontal translation of the matte"
        },
        "ty": {
          "type": "number",
          "description": "Vertical translation of the matte"
        }
      }
    },
    "warp": {
      "type": "string",
      "description": "Warp type of the matte",
      "enum": [
        "None",
        "Equi360",
        "Equi180"
      ]
    },
    "warp_blur_filter": {
      "type": "number",
      "description": "Warp blur filter"
    },
    "warp_equi_dist": {
      "type": "number",
      "description": "Warp equi distance"
    }
  }
}

