bodySchema:
{
  "type": "object",
  "title": "tray_data",
  "description": "A Tray is a project level container that holds shots (references).",
  "required": [
    "name"
  ],
  "properties": {
    "name": {
      "description": "Name of the Tray",
      "type": "string"
    },
    "uuid": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
      "minLength": 36,
      "maxLength": 36,
      "description": "UUID format as per RFC 4122"
    },
    "selected": {
      "type": "boolean",
      "description": "Whether the tray the selected tray in the project"
    },
    "tray_shots": {
      "type": "array",
      "items": {
        "type": "object",
        "title": "tray_shot_data",
        "description": "A Tray shot is an entry in a Tray that holds a reference to a Shot.",
        "required": [
          "uuid"
        ],
        "properties": {
          "shot_uuid": {
            "type": "string",
            "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
            "minLength": 36,
            "maxLength": 36,
            "description": "UUID format as per RFC 4122"
          },
          "position": {
            "type": "integer",
            "description": "Index position of the tray item in the tray"
          },
          "selected": {
            "type": "boolean",
            "description": "Whether the tray item in the tray is selected"
          },
          "slip": {
            "type": "integer",
            "description": "Slip in frames for split view playback"
          },
          "ref_frame": {
            "type": "integer",
            "description": "Reference frame for proxy view in the tray"
          },
          "shot": {
            "type": "object",
            "description": "Shot data",
            "title": "Shot data",
            "properties": {
              "uuid": {
                "type": "string",
                "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                "minLength": 36,
                "maxLength": 36,
                "description": "UUID format as per RFC 4122"
              },
              "type_uuid": {
                "type": "string",
                "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                "minLength": 36,
                "maxLength": 36,
                "description": "UUID format as per RFC 4122"
              },
              "file": {
                "type": "string",
                "description": "Full filename of the Shot media"
              },
              "name": {
                "description": "Name of the Shot",
                "type": "string"
              },
              "node_preset_file": {
                "description": "File path to the .pls (plugin preset) file. Input only.",
                "type": "string"
              },
              "color_settings_file": {
                "description": "File path to the .ccr (color settings) file. Input only",
                "type": "string"
              },
              "reel_id": {
                "type": "string",
                "description": "Reel identifier"
              },
              "scene": {
                "description": "Scene identifier",
                "type": "string"
              },
              "take": {
                "description": "Take identifier",
                "type": "string"
              },
              "circled": {
                "description": "Circle Shot y/n",
                "type": "boolean"
              },
              "fps": {
                "type": "number",
                "description": "Frames per second of the shot"
              },
              "fps_multiplier": {
                "description": "FPS multiplier for retiming",
                "type": "number"
              },
              "fps_offset": {
                "description": "FPS offset for retiming",
                "type": "number"
              },
              "fps_mode": {
                "description": "FPS mode for retiming (0 = Nearest Frame, 1 = Rolling Mix)",
                "type": "integer"
              },
              "frame_tc": {
                "type": "integer",
                "description": "Frame number of the Shot timecode"
              },
              "timecode": {
                "type": "string",
                "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
                "minLength": 11,
                "maxLength": 11,
                "description": "Timecode HH:MM:SS:FF"
              },
              "length": {
                "type": "integer",
                "description": "Length of the Shot in frames"
              },
              "handles": {
                "type": "object",
                "properties": {
                  "frame_in": {
                    "type": "integer",
                    "description": "In-point of the Shot"
                  },
                  "frame_out": {
                    "type": "integer",
                    "description": "Out-point of the Shot"
                  },
                  "start": {
                    "type": "string",
                    "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "minLength": 11,
                    "maxLength": 11,
                    "description": "Timecode HH:MM:SS:FF"
                  },
                  "end": {
                    "type": "string",
                    "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "minLength": 11,
                    "maxLength": 11,
                    "description": "Timecode HH:MM:SS:FF"
                  }
                }
              },
              "size": {
                "type": "object",
                "description": "Resolution of the Shot in pixels",
                "properties": {
                  "width": {
                    "type": "integer"
                  },
                  "height": {
                    "type": "integer"
                  }
                }
              },
              "aspect": {
                "type": "number",
                "description": "Aspect ratio of the Shot"
              },
              "output": {
                "type": "object",
                "description": "Output settings for rendering the individual Shot",
                "properties": {
                  "outputpath": {
                    "type": "string",
                    "description": "Output folder for the render"
                  },
                  "filespec": {
                    "type": "string",
                    "description": "File specification / mask for the render. Include mask codes to dynamically create the output filename. See the documentation for details."
                  },
                  "format": {
                    "type": "integer",
                    "description": "Format mask is a combination of bit depth and component type. 0 (8bit), 1 (10bit), 2 (16bit int), 3 (16bit float), 4 (32bit float). Note that most media formats only allow for specific combinations of bit depth and type. Not all combinations are valid. Check the sotware UI for valid combinations."
                  },
                  "components": {
                    "type": "integer",
                    "description": "Channel count (3 for RGB, 4 for RGBA)"
                  },
                  "extention": {
                    "enum": [
                      "tif",
                      "dpx",
                      "cin",
                      "jpg",
                      "tga",
                      "j2c",
                      "png",
                      "exr"
                    ],
                    "description": "File extension"
                  }
                }
              },
              "framing": {
                "type": "object",
                "description": "Shot framing in a timeline context",
                "properties": {
                  "offset": {
                    "type": "object",
                    "description": "2D Vector",
                    "properties": {
                      "x": {
                        "description": "x value",
                        "type": "number"
                      },
                      "y": {
                        "description": "y value",
                        "type": "number"
                      }
                    }
                  },
                  "scale": {
                    "type": "object",
                    "description": "2D Vector",
                    "properties": {
                      "x": {
                        "description": "x value",
                        "type": "number"
                      },
                      "y": {
                        "description": "y value",
                        "type": "number"
                      }
                    }
                  },
                  "rotate": {
                    "type": "number",
                    "description": "Rotation angle in degrees"
                  },
                  "opacity": {
                    "type": "number",
                    "description": "Opacity percentage"
                  },
                  "animation": {
                    "type": "object",
                    "properties": {
                      "channels": {
                        "description": "List of animation channels",
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "id": {
                              "type": "string",
                              "description": "Name of the Animation channel"
                            },
                            "key_frames": {
                              "type": "array",
                              "items": {
                                "type": "object",
                                "properties": {
                                  "li": {
                                    "type": "number",
                                    "description": "Left tangent line position"
                                  },
                                  "lv": {
                                    "type": "number",
                                    "description": "Left tangent line value"
                                  },
                                  "ki": {
                                    "type": "number",
                                    "description": "Key position"
                                  },
                                  "kv": {
                                    "type": "number",
                                    "description": "Key value"
                                  },
                                  "ri": {
                                    "type": "number",
                                    "description": "Right tangent line position"
                                  },
                                  "rv": {
                                    "type": "number",
                                    "description": "Right tangent line value"
                                  }
                                },
                                "required": [
                                  "ki",
                                  "kv"
                                ]
                              }
                            },
                            "pre": {
                              "type": "string",
                              "description": "Pre interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                            },
                            "post": {
                              "type": "string",
                              "description": "Post interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                            }
                          }
                        }
                      }
                    }
                  }
                }
              },
              "view": {
                "type": "object",
                "properties": {
                  "projection_type": {
                    "description": "Projection type",
                    "enum": [
                      "normal",
                      "equirectangular 360",
                      "equirectangular-180",
                      "cubic",
                      "cubic-packed",
                      "mesh"
                    ]
                  },
                  "stereo_mode": {
                    "description": "Stereo mode",
                    "enum": [
                      "mono",
                      "stereo",
                      "left-right",
                      "top-bottom"
                    ]
                  }
                }
              },
              "orientation": {
                "type": "object",
                "description": "Shot Orientation",
                "properties": {
                  "flip": {
                    "type": "boolean",
                    "description": "Invert Shot horizontally"
                  },
                  "flop": {
                    "type": "boolean",
                    "description": "Invert Shot vertically"
                  }
                }
              },
              "color_format": {
                "type": "object",
                "description": "Color format of the Shot",
                "properties": {
                  "colorspace": {
                    "description": "Color space",
                    "enum": [
                      "ACES (AP0)",
                      "ACEScg (AP1)",
                      "Adobe RGB (1998)",
                      "Adobe Wide Gamut",
                      "Apple Wide Gamut",
                      "ARRI Wide Gamut 3",
                      "ARRI Wide Gamut 4",
                      "Blackmagic DWG",
                      "BMD Wide Gamut",
                      "Canon Cinema Gamut",
                      "DCI XYZ",
                      "DJI D-Gamut",
                      "Fujifilm F-Gamut C",
                      "P3 D60",
                      "P3 D65",
                      "P3 DCI",
                      "Panasonic V-Gamut",
                      "Rec2020",
                      "Rec709",
                      "RED Wide Gamut",
                      "Sony S-Gamut3",
                      "Sony S-Gamut3 Cine",
                      "sRGB",
                      "XYZ"
                    ]
                  },
                  "eotf": {
                    "description": "EOTF (Electro-Optical Transfer Function)",
                    "enum": [
                      "ACEScc",
                      "ACEScct",
                      "Apple Log",
                      "ARRI LogC3",
                      "ARRI LogC4",
                      "Blackmagic DI",
                      "BMD Film",
                      "BMD Film Gen 5",
                      "Canon Log2",
                      "Canon Log3",
                      "Cineon Log",
                      "DJI D-Log",
                      "Fujifilm F-Log",
                      "Fujifilm F-Log2",
                      "Gamma 2.2",
                      "Gamma 2.4",
                      "Gamma 2.6 (DCI)",
                      "HLG HDR",
                      "HLG Scene HDR",
                      "Leica L-Log",
                      "Nikon N-Log",
                      "Panasonic V-Log",
                      "PQ HDR",
                      "RED Log3G10",
                      "Scene Linear",
                      "Sony S-Log2",
                      "Sony S-Log3"
                    ]
                  },
                  "apply": {
                    "type": "boolean",
                    "description": "Apply an automatic transformation on the node input if the color space or transfer function differs (only available with Transformer nodes)"
                  },
                  "lut": {
                    "type": "string",
                    "description": "LUT applied to the shot"
                  }
                }
              },
              "colorgrade": {
                "type": "object",
                "title": "colorgrade",
                "description": "Shot colorgrade metadata",
                "properties": {
                  "offset": {
                    "type": "object",
                    "properties": {
                      "b": {
                        "type": "number",
                        "description": "Blue channel offset"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel offset"
                      },
                      "m": {
                        "type": "number",
                        "description": "Master offset"
                      },
                      "r": {
                        "type": "number",
                        "description": "Red channel offset"
                      }
                    }
                  },
                  "pre_gain": {
                    "type": "object",
                    "properties": {
                      "b": {
                        "type": "number",
                        "description": "Blue channel pre gain"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel pre gain"
                      },
                      "m": {
                        "type": "number",
                        "description": "Master pre gain"
                      },
                      "r": {
                        "type": "number",
                        "description": "Red channel pre gain"
                      }
                    }
                  },
                  "color_a": {
                    "type": "object",
                    "description": "Pre-Color",
                    "properties": {
                      "h": {
                        "type": "number",
                        "description": "Hue"
                      },
                      "l": {
                        "type": "number",
                        "description": "Brightness"
                      },
                      "s": {
                        "type": "number",
                        "description": "Saturation"
                      }
                    }
                  },
                  "lift": {
                    "type": "object",
                    "properties": {
                      "b": {
                        "type": "number",
                        "description": "Blue channel lift"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel lift"
                      },
                      "m": {
                        "type": "number",
                        "description": "Master lift"
                      },
                      "r": {
                        "type": "number",
                        "description": "Red channel lift"
                      }
                    }
                  },
                  "gamma": {
                    "type": "object",
                    "description": "Gamma",
                    "properties": {
                      "b": {
                        "type": "number",
                        "description": "Blue channel gamma"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel gamma"
                      },
                      "r": {
                        "type": "number",
                        "description": "Red channel gamma"
                      },
                      "m": {
                        "type": "number",
                        "description": "Master gamma"
                      }
                    }
                  },
                  "gain": {
                    "type": "object",
                    "description": "Gain",
                    "properties": {
                      "b": {
                        "type": "number",
                        "description": "Blue channel gain"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel gain"
                      },
                      "r": {
                        "type": "number",
                        "description": "Red channel gain"
                      },
                      "m": {
                        "type": "number",
                        "description": "Master gain"
                      }
                    }
                  },
                  "color_b": {
                    "type": "object",
                    "description": "Post-Color",
                    "properties": {
                      "h": {
                        "type": "number",
                        "description": "Hue"
                      },
                      "l": {
                        "type": "number",
                        "description": "Brightness"
                      },
                      "s": {
                        "type": "number",
                        "description": "Saturation"
                      }
                    }
                  },
                  "tone": {
                    "type": "object",
                    "properties": {
                      "c": {
                        "type": "number",
                        "description": "Contrast"
                      },
                      "i": {
                        "type": "number",
                        "description": "ISO Gain"
                      },
                      "s": {
                        "type": "number",
                        "description": "S Curve"
                      }
                    }
                  },
                  "temperature": {
                    "type": "object",
                    "properties": {
                      "k": {
                        "type": "number",
                        "description": "Kelvin temperature"
                      },
                      "t": {
                        "type": "number",
                        "description": "Tint"
                      }
                    }
                  },
                  "aperature": {
                    "type": "object",
                    "title": "Aperature",
                    "description": "Aperature",
                    "properties": {
                      "c": {
                        "type": "number",
                        "description": "Clarity"
                      },
                      "d": {
                        "type": "number",
                        "description": "Defocus"
                      }
                    }
                  },
                  "noise": {
                    "type": "number",
                    "description": "Amount of noise to add to the shot"
                  },
                  "channel_invert": {
                    "type": "boolean",
                    "description": "Whether to invert the color channels"
                  },
                  "channel_remap": {
                    "type": "string",
                    "pattern": "^[RBG0]{3}[A0RGB1]$",
                    "minLength": 4,
                    "maxLength": 4,
                    "description": "Remapping of color channels"
                  },
                  "soft_clip_high": {
                    "type": "object",
                    "description": "Soft clip high value",
                    "properties": {
                      "r": {
                        "type": "number",
                        "description": "Red channel soft clip high value"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel soft clip high value"
                      },
                      "b": {
                        "type": "number",
                        "description": "Blue channel soft clip high value"
                      }
                    }
                  },
                  "soft_clip_low": {
                    "type": "object",
                    "description": "Soft clip low value",
                    "properties": {
                      "r": {
                        "type": "number",
                        "description": "Red channel soft clip low value"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel soft clip low value"
                      },
                      "b": {
                        "type": "number",
                        "description": "Blue channel soft clip low value"
                      }
                    }
                  },
                  "clip_high": {
                    "type": "object",
                    "description": "Clip high value",
                    "properties": {
                      "r": {
                        "type": "number",
                        "description": "Red channel clip high value"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel clip high value"
                      },
                      "b": {
                        "type": "number",
                        "description": "Blue channel clip high value"
                      }
                    }
                  },
                  "clip_low": {
                    "type": "object",
                    "description": "Clip low value",
                    "properties": {
                      "r": {
                        "type": "number",
                        "description": "Red channel clip low value"
                      },
                      "g": {
                        "type": "number",
                        "description": "Green channel clip low value"
                      },
                      "b": {
                        "type": "number",
                        "description": "Blue channel clip low value"
                      }
                    }
                  },
                  "lut": {
                    "type": "string",
                    "description": "LUT applied to the colorgrade"
                  }
                }
              },
              "camera": {
                "type": "object",
                "description": "Camera Data",
                "title": "Camera Data",
                "properties": {
                  "active": {
                    "type": "boolean",
                    "description": "Activate / deactivate the camera"
                  },
                  "focal_length": {
                    "type": "number",
                    "description": "Focal length / Zoom"
                  },
                  "focus_distance": {
                    "type": "number",
                    "description": "Focus distance"
                  },
                  "sensor_width": {
                    "type": "number",
                    "description": "Sensor width"
                  },
                  "sensor_height": {
                    "type": "number",
                    "description": "Sensor height"
                  },
                  "sensor_crop": {
                    "description": "Sensor crop",
                    "type": "number"
                  },
                  "bypass": {
                    "description": "By-pass the camera translation and rotation for rendering",
                    "type": "boolean"
                  },
                  "position": {
                    "type": "object",
                    "description": "Camera origin position and rotation",
                    "properties": {
                      "tx": {
                        "type": "number",
                        "description": "Translation X"
                      },
                      "ty": {
                        "description": "Translation Y",
                        "type": "number"
                      },
                      "tz": {
                        "description": "Translation Z",
                        "type": "number"
                      },
                      "rx": {
                        "type": "number",
                        "description": "Rotation X"
                      },
                      "ry": {
                        "type": "number",
                        "description": "Rotation Y"
                      },
                      "rz": {
                        "type": "number",
                        "description": "Rotation Z"
                      },
                      "manual": {
                        "description": "Auto position the virtual camera based on focal length",
                        "type": "boolean"
                      },
                      "pscale": {
                        "description": "Pixel meter scale",
                        "type": "number"
                      }
                    }
                  },
                  "offset": {
                    "type": "object",
                    "description": "Camera offset position and rotation",
                    "properties": {
                      "tx": {
                        "type": "number",
                        "description": "Translation X"
                      },
                      "ty": {
                        "type": "number",
                        "description": "Translation Y"
                      },
                      "tz": {
                        "type": "number",
                        "description": "Translation Z"
                      },
                      "rx": {
                        "type": "number",
                        "description": "Rotation X"
                      },
                      "ry": {
                        "type": "number",
                        "description": "Rotation Y"
                      },
                      "rz": {
                        "type": "number"
                      }
                    }
                  },
                  "animation": {
                    "type": "object",
                    "properties": {
                      "channels": {
                        "description": "List of animation channels",
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "id": {
                              "type": "string",
                              "description": "Name of the Animation channel"
                            },
                            "key_frames": {
                              "type": "array",
                              "items": {
                                "type": "object",
                                "properties": {
                                  "li": {
                                    "type": "number",
                                    "description": "Left tangent line position"
                                  },
                                  "lv": {
                                    "type": "number",
                                    "description": "Left tangent line value"
                                  },
                                  "ki": {
                                    "type": "number",
                                    "description": "Key position"
                                  },
                                  "kv": {
                                    "type": "number",
                                    "description": "Key value"
                                  },
                                  "ri": {
                                    "type": "number",
                                    "description": "Right tangent line position"
                                  },
                                  "rv": {
                                    "type": "number",
                                    "description": "Right tangent line value"
                                  }
                                },
                                "required": [
                                  "ki",
                                  "kv"
                                ]
                              }
                            },
                            "pre": {
                              "type": "string",
                              "description": "Pre interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                            },
                            "post": {
                              "type": "string",
                              "description": "Post interpolation type \"C\" \"L\" \"P\" \"B\" constant, linear, loop, bounce"
                            }
                          }
                        }
                      }
                    }
                  }
                }
              },
              "mos": {
                "type": "boolean",
                "description": "Mit Ohne Sound Shot"
              },
              "audio": {
                "type": "object",
                "description": "Audio settings of the Shot",
                "properties": {
                  "timecode": {
                    "type": "string",
                    "pattern": "^[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "minLength": 11,
                    "maxLength": 11,
                    "description": "Timecode HH:MM:SS:FF"
                  },
                  "slip": {
                    "type": "number",
                    "description": "Slip in milliseconds of all audio items to the video"
                  },
                  "roll": {
                    "type": "number",
                    "description": "Roll identifier"
                  },
                  "items": {
                    "type": "array",
                    "description": "List of audio items",
                    "items": {
                      "type": "object",
                      "properties": {
                        "file": {
                          "type": "string",
                          "description": "File path of the audio item. 'embedded' if the Shot has embedded audio."
                        },
                        "offset": {
                          "type": "integer",
                          "description": "Offset in milliseconds of the individual audio item to the video"
                        }
                      }
                    }
                  }
                }
              },
              "metadata": {
                "type": "array",
                "title": "Metadata",
                "description": "Metadata list of key-value pairs",
                "items": {
                  "type": "object",
                  "properties": {
                    "key": {
                      "type": "string",
                      "description": "Metadata key"
                    },
                    "value": {
                      "type": "string",
                      "description": "Metadata value"
                    }
                  }
                }
              },
              "notes": {
                "type": "array",
                "description": "Notes of the Shot",
                "items": {
                  "type": "object",
                  "title": "note_data",
                  "description": "Note",
                  "properties": {
                    "status": {
                      "type": "integer",
                      "description": "Color of the note"
                    },
                    "author": {
                      "type": "string",
                      "description": "Author of the note"
                    },
                    "frame": {
                      "type": "integer",
                      "description": "Frame number in the Shot of the note"
                    },
                    "id": {
                      "type": "integer",
                      "description": "Unique identifier of the note"
                    },
                    "note": {
                      "type": "string",
                      "description": "Content of the note"
                    }
                  }
                }
              },
              "staging": {
                "type": "array",
                "description": "List of Staging Shots",
                "items": {
                  "type": "object",
                  "properties": {
                    "stage_shot_uuid": {
                      "type": "string",
                      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                      "minLength": 36,
                      "maxLength": 36,
                      "description": "UUID format as per RFC 4122"
                    },
                    "shot": {
                      "description": "Recursive reference",
                      "type": "object"
                    }
                  }
                }
              },
              "inputs": {
                "type": "array",
                "items": {
                  "type": "object",
                  "title": "input_data",
                  "description": "Input Shot of a (parent) Shot",
                  "properties": {
                    "index": {
                      "type": "integer",
                      "description": "Index of the Input Shot in the parent Shot"
                    },
                    "grade": {
                      "type": "boolean",
                      "description": "render the grade of the Input Shot"
                    },
                    "create_copy": {
                      "type": "boolean",
                      "description": "Create a copy of the Shot or use a reference"
                    },
                    "input_uuid": {
                      "type": "string",
                      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                      "minLength": 36,
                      "maxLength": 36,
                      "description": "UUID format as per RFC 4122"
                    },
                    "input": {
                      "description": "Recursive reference",
                      "type": "object"
                    },
                    "length": {
                      "type": "integer",
                      "description": "Length of the Input Shot in frames"
                    },
                    "loop_mode": {
                      "enum": [
                        "Once",
                        "Loop",
                        "Bounce",
                        "Reverse"
                      ],
                      "description": "Loop mode of the Input Shot"
                    },
                    "slip": {
                      "type": "integer",
                      "description": "Shot in-point."
                    }
                  }
                }
              },
              "controls": {
                "type": "array",
                "items": {
                  "type": "object",
                  "title": "control_data",
                  "description": "Individual control data item",
                  "required": [
                    "id",
                    "value"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "description": "Unique identifier of the control (readonly)"
                    },
                    "name": {
                      "type": "string",
                      "description": "Name of the control"
                    },
                    "type": {
                      "type": "string",
                      "description": "Type of the control - 'Option', 'Text', 'Boolean', etc. (readonly)",
                      "enum": [
                        "Option",
                        "Text",
                        "MText",
                        "Boolean",
                        "Numeric",
                        "Color",
                        "Menu"
                      ]
                    },
                    "value": {
                      "description": "Value of the control (string representation for all types)",
                      "oneOf": [
                        {
                          "type": "boolean"
                        },
                        {
                          "type": "string"
                        },
                        {
                          "type": "number"
                        },
                        {
                          "type": "object",
                          "properties": {
                            "r": {
                              "type": "number",
                              "description": "Red channel value"
                            },
                            "g": {
                              "type": "number",
                              "description": "Green channel value"
                            },
                            "b": {
                              "type": "number",
                              "description": "Blue channel value"
                            },
                            "a": {
                              "type": "number",
                              "description": "Alpha channel value",
                              "required": [
                                "r",
                                "g",
                                "b",
                                "a"
                              ],
                              "additionalProperties": false
                            }
                          }
                        }
                      ]
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

