                "Panasonic V-Gamut",
                "Rec2020",
                "Rec709",
                "RED Wide Gamut",
                "Sony S-Gamut3",
                "Sony S-Gamut3 Cine",
                "sRGB",
                "XYZ"
              ]
            },
            "eotf": {
              "description": "EOTF (Electro-Optical Transfer Function)",
              "enum": [
                "ACEScc",
